platform_resolve() {
  local p="${PLATFORM:-github}"
  if [[ "$PLATFORM" == "tangled" && -z "${TANGLED_REPO_DID:-}" ]]; then
    return 1
  fi
  printf '%s' "$p"
}

_platform_is_forgejo() {
  [[ "$(platform_resolve)" == "forgejo" ]]
}

platform_pr_diff() {
  if _platform_is_forgejo; then
    forgejo_diff "$@"
  else
    gh pr diff "$@"
  fi
}

